namespace sv_429f256ade0d499bb49318c5cc598025.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private CancellationTokenSource? _pollCts;
    private int _subscriberCount;
    private readonly Lock _lock = new();

    public int CurrentLowStockCount { get; private set; }

    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>Simulates a database query returning low-stock item count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(Random.Shared.Next(0, 16));
    }

    /// <summary>
    /// Call when a component wants polling to be active.
    /// Polling starts on the first subscriber, stops when the last unsubscribes.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _pollCts = new CancellationTokenSource();
                _ = PollLoopAsync(_pollCts.Token);
            }
        }
    }

    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                _pollCts?.Cancel();
                _pollCts?.Dispose();
                _pollCts = null;
            }
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire immediately on start, then every 10 seconds.
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await RefreshAsync();
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    private async Task RefreshAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        await NotifySubscribersAsync();
    }

    private async void HandleWarehouseChanged()
    {
        // When the warehouse changes mid-poll, refresh immediately.
        await RefreshAsync();
    }

    private async Task NotifySubscribersAsync()
    {
        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _pollCts?.Cancel();
        _pollCts?.Dispose();
        OnAlertCountChanged = null;
    }
}

