@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouseSelect" class="form-label mb-0 me-2 text-nowrap">
        <strong>📦 Warehouse:</strong>
    </label>
    <select id="warehouseSelect" class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.Warehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        WarehouseState.CurrentWarehouseId = e.Value?.ToString() ?? "";
    }

    // Re-render if something else changes the warehouse programmatically.
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<span class="alert-badge" title="Low-stock items">
    @if (AlertService.CurrentLowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@AlertService.CurrentLowStockCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += OnAlertCountChanged;
    }

    private async Task OnAlertCountChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>📊 Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-5">
            <strong>@WarehouseState.CurrentWarehouseName</strong>
            <span class="text-muted">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="row">
    <div class="col-md-4 mb-3">
        <div class="card @(AlertService.CurrentLowStockCount > 10 ? "border-danger" :
                            AlertService.CurrentLowStockCount > 5  ? "border-warning" :
                            "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 mb-0">
                    @AlertService.CurrentLowStockCount
                </p>
                <small class="text-muted">items below minimum level</small>
            </div>
        </div>
    </div>

    <div class="col-md-8 mb-3">
        <div class="card h-100">
            <div class="card-body">
                <h5 class="card-title">Alert Status</h5>
                @if (AlertService.CurrentLowStockCount == 0)
                {
                    <div class="alert alert-success mb-0">
                        ✅ All inventory levels are healthy at <strong>@WarehouseState.CurrentWarehouseName</strong>.
                    </div>
                }
                else if (AlertService.CurrentLowStockCount <= 5)
                {
                    <div class="alert alert-info mb-0">
                        ℹ️ <strong>@AlertService.CurrentLowStockCount</strong> items need attention. Consider re-ordering soon.
                    </div>
                }
                else if (AlertService.CurrentLowStockCount <= 10)
                {
                    <div class="alert alert-warning mb-0">
                        ⚠️ <strong>@AlertService.CurrentLowStockCount</strong> items are running low. Initiate replenishment.
                    </div>
                }
                else
                {
                    <div class="alert alert-danger mb-0">
                        🚨 <strong>@AlertService.CurrentLowStockCount</strong> items critically low! Immediate action required.
                    </div>
                }
                <p class="text-muted mt-2 mb-0"><small>Data refreshes every 10 seconds while this page is open.</small></p>
            </div>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
        AlertService.OnAlertCountChanged += OnAlertCountChanged;

        // Start polling — this page is the driver of the poll loop.
        AlertService.StartPolling();
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    private async Task OnAlertCountChanged() => await InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
        AlertService.OnAlertCountChanged -= OnAlertCountChanged;
        AlertService.StopPolling();
    }
}

